"""
    tilted_L1(u; quant) = quant * [u]_+ + (1 - quant) * [u]_
    """
def tilted_L1(u: Any, quantile: Any = 0.5) -> object {
    return ((0.5 * abs(u)) + ((quantile - 0.5) * u));
}

